import os
import smtplib
import json
import boto3
from email.mime.text import MIMEText
from email.mime.multipart import MIMEMultipart
from botocore.exceptions import ClientError

class EmailService:
    """
    Service for sending emails via SMTP using Gmail.
    Credentials are fetched from AWS Secrets Manager.
    """
    def __init__(self):
        # FEEDBACK_SECRET_ID should be set in environment. 
        # Defaulting to the name generated by Terraform for easier local development.
        self.secret_id = os.environ.get("FEEDBACK_SECRET_ID", "KnowYourMLA-feedback-credentials-prod")
        self.aws_region = os.environ.get("AWS_REGION", "ap-south-2")
        self.client = boto3.client("secretsmanager", region_name=self.aws_region)

    def _get_credentials(self):
        """
        Fetches Gmail credentials from AWS Secrets Manager.
        """
        try:
            response = self.client.get_secret_value(SecretId=self.secret_id)
            if "SecretString" in response:
                return json.loads(response["SecretString"])
            return None
        except ClientError as e:
            print(f"Error fetching secret: {e}")
            return None

    def send_feedback(
        self,
        message: str,
        url: str,
        name: str = None,
        email: str = None,
        subject: str = None,
    ) -> bool:
        """
        Sends feedback or data requests via email.

        Args:
            message: The user's message or request details.
            url: The page URL where the request was submitted.
            name: Optional name of the user.
            email: Optional email of the user.
            subject: Optional subject for the email.

        Returns:
            True if sent successfully, False otherwise.
        """
        creds = self._get_credentials()
        if not creds:
            return False

        username = creds.get("username")
        password = creds.get("password")

        if not username or not password:
            return False

        recipient = os.environ.get("FEEDBACK_RECIPIENT_EMAIL", "ptsntamil1@gmail.com")

        # Create the email message
        msg = MIMEMultipart()
        msg["From"] = username
        msg["To"] = recipient
        msg["Subject"] = subject or "User Feedback from KnowYourMLA"
        if email:
            msg["Reply-To"] = email

        email_title = subject or "User Feedback"
        body = f"""
        {email_title}:
        --------------------------------------------------
        Name: {name or 'Not provided'}
        Email: {email or 'Not provided'}
        Message: {message}
        --------------------------------------------------
        
        Submitted from URL: {url}
        """
        msg.attach(MIMEText(body, "plain"))

        try:
            # Connect to Gmail SMTP server
            server = smtplib.SMTP("smtp.gmail.com", 587)
            server.starttls()
            server.login(username, password)
            text = msg.as_string()
            server.sendmail(username, recipient, text)
            server.quit()
            return True
        except Exception as e:
            print(f"Error sending email: {e}")
            return False
